let books=[],roots=[],settings={},tab='library',current,selectedBook,selectedChapter=0,activeChapter=-1,activeFile='',blobURL='',sleepTimer,worker,speechPending,transcribing=false,cancelled=false,selectedCues=[],sceneCount=1,sceneAccepted=false,installPrompt;
let ownsPlayback=false;
let currentProgress={index:0,time:0,speed:1,updated:0},coverURLs=new Map(),imageURLs=[];
