content.addEventListener('click',ev=>{const button=ev.target.closest('[data-action]');if(button)Promise.resolve(handle(button.dataset.action,button,ev)).catch(fail);});
$('restore-file').onchange=async ev=>{try{const f=ev.target.files[0];if(!f)return;if(f.size>10000000)throw Error('This backup is too large.');const value=JSON.parse(await f.text());if(value.format!=='narrumo-desktop'||value.version!==1||!Array.isArray(value.books)||value.books.length>1000||!Array.isArray(value.roots))throw Error('Choose a Narrumo desktop progress backup.');for(const b of value.books){if(typeof b.id!=='string'||!/^[a-f0-9]{64}$/.test(b.id)||typeof b.title!=='string'||b.title.length>500||!Array.isArray(b.chapters)||!b.chapters.length||b.chapters.length>10000)throw Error('Invalid book data.');for(const c of b.chapters)if(typeof c.fileId!=='string'||typeof c.title!=='string'||!Number.isFinite(c.start)||c.start<0||!Number.isFinite(c.duration)||c.duration<=0)throw Error('Invalid chapter data.');}modal('Restore saved places?','Merges this backup into your local library. Matching books use the backup’s progress and bookmarks. Audio and credentials are not imported; reconnect folders afterward.',[['Restore backup',async()=>{for(const b of value.books){await db.put('books',{...books.find(x=>x.id===b.id),...b});localStorage.setItem('narrumo-progress:'+b.id,JSON.stringify(position(b,b.progress)));}for(const root of value.roots)if(typeof root.id==='string'&&typeof root.name==='string'&&!roots.some(r=>r.id===root.id))await db.put('roots',{id:root.id,name:root.name});books=await db.all('books');roots=await db.all('roots');notice('Progress restored. Reconnect folders in Settings if needed.');show('library');},true]]);}catch(err){fail(err);}ev.target.value='';};
async function importTranscript(){const input=document.createElement('input');input.type='file';input.accept='.srt,.vtt';input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(f.size>3000000)throw Error('Choose a timed-text file under 3 MB.');const text=(await f.text()).replace(/\r/g,'');const cues=[];const pattern=/(?:(\d+):)?(\d{2}):(\d{2})[.,](\d{3})\s*-->\s*(?:(\d+):)?(\d{2}):(\d{2})[.,](\d{3})[^\n]*\n([\s\S]*?)(?=\n\s*\n|$)/g;let m;while((m=pattern.exec(text))){const t=n=>(Number(m[n]||0)*3600+Number(m[n+1])*60+Number(m[n+2])+Number(m[n+3])/1000);cues.push({start:t(1),end:t(5),text:m[9].replace(/<[^>]*>/g,'').trim()});}const b=selected(),index=selectedChapter,c=b.chapters[index];validateCues(cues,c.duration);if(!cues.length)throw Error('No valid SRT/VTT cues found.');modal('Import this transcript?','Replaces chapter transcript text with the chosen timed text. Future text is hidden until heard. The previous transcript is preserved locally.',[['Import chapter text',async()=>{const w=await workFor(b,index);await db.put('work',{...w,id:w.id+'|previous'});await db.put('work',{...w,cues,processed:Math.min(c.duration,cues.at(-1).end),engine:'Imported timed text'});selectedCues=[];show('ai');},true]]);}catch(err){fail(err);}};input.click();}
$('add-folder').onclick=()=>chooseFolder().catch(fail);$('mini-open').onclick=()=>show('player');$('mini-toggle').onclick=()=>toggle().catch(fail);document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>show(el.dataset.tab));
audio.addEventListener('timeupdate',updatePlayback);audio.addEventListener('pause',()=>{saveProgress();updatePlayback();});audio.addEventListener('play',updatePlayback);audio.addEventListener('seeked',()=>{saveProgress();updatePlayback();if(tab==='ai'){if($('dialog').open)$('dialog').close();aiView();}});audio.addEventListener('ended',advance);audio.addEventListener('error',()=>notice('This audio file could not be played. Reconnect the folder or try a supported format.'));
setInterval(()=>{if(!audio.paused)saveProgress();if(tab==='ai'&&$('dialog').open){const b=selected(),p=progress(b);if(selectedChapter>p.index)$('dialog').close();}},2000);window.addEventListener('pagehide',saveProgress);document.addEventListener('visibilitychange',saveProgress);window.addEventListener('keydown',ev=>{if(['INPUT','TEXTAREA','SELECT','BUTTON'].includes(document.activeElement?.tagName)||$('dialog').open)return;if(ev.code==='Space'&&current){ev.preventDefault();toggle().catch(fail);}else if(ev.code==='ArrowLeft'&&activeChapter>=0){audio.currentTime=Math.max(current.chapters[activeChapter].start,audio.currentTime-15);}else if(ev.code==='ArrowRight'&&activeChapter>=0){audio.currentTime=Math.min(current.chapters[activeChapter].start+current.chapters[activeChapter].duration,audio.currentTime+30);}});
if('mediaSession'in navigator)for(const [name,fn]of Object.entries({play:()=>audio.paused?toggle():undefined,pause:()=>audio.pause(),seekbackward:()=>audio.currentTime=Math.max(current.chapters[activeChapter].start,audio.currentTime-15),seekforward:()=>audio.currentTime=Math.min(current.chapters[activeChapter].start+current.chapters[activeChapter].duration,audio.currentTime+30),previoustrack:()=>loadBook(current,Math.max(0,activeChapter-1),0,true),nexttrack:()=>advance()}))try{navigator.mediaSession.setActionHandler(name,fn);}catch{}
