async function init(){try{settings=(await db.get('settings','preferences'))||{};if(/^#[a-f0-9]{6}$/i.test(settings.accent||''))document.documentElement.style.setProperty('--accent',settings.accent);books=(await db.all('books')).sort((a,b)=>natural(a.title,b.title));roots=await db.all('roots');current=books.find(b=>b.id===localStorage.getItem('narrumo-current'));show('library');if('serviceWorker'in navigator){await navigator.serviceWorker.register('./sw.js',{scope:'./'});navigator.serviceWorker.ready.then(()=>$('offline-state').textContent='LOCAL LIBRARY · OFFLINE APP READY');}}catch(err){content.innerHTML=heading('A little pause.','Narrumo needs browser storage to keep your library.');fail(err);}}
